import os, re, glob
d = '.handoffs'
idx = []
for ln in open(d + '/INDEX.md'):
    m = re.match(r'^- \[`([^`]+)`\]\([^)]+\)\s*[—-]\s*(.+)$', ln.rstrip('\n'))
    if m:
        idx.append((m.group(1), m.group(2).strip()))
def first_heading(path):
    for ln in open(path, encoding='utf-8', errors='replace'):
        s = ln.strip()
        if s.startswith('#') and not s.startswith('###'):
            return re.sub(r'^#+\s*', '', s).strip()
    return None
mismatch = []
for fname, entry in idx:
    h = first_heading(os.path.join(d, fname))
    if h is None:
        mismatch.append((fname, 'NO HEADING', entry)); continue
    # normalize: strip leading numeric prefix and asterisks from entry
    norm = re.sub(r'^\d+\s*[-—]\s*', '', entry).strip('*').strip()
    if norm.lower() not in h.lower():
        mismatch.append((fname, h, entry))
print('checked', len(idx), 'entries')
print('mismatches:', len(mismatch))
for x in mismatch:
    print(x)
PYEOF
